// AI-assisted (Claude Code): first draft generated by AI, then reviewed, tested and edited by me.

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../AppTheme.css';
import AddressFields from '../components/AddressFields';
import Footer from '../components/Footer';
import Navbar from '../components/Navbar';
import { registerCustomer, validateAddress } from '../data/account';

// Empty object for form used to reset on pageload/after submission
const EMPTY_FORM = {
  name: '',
  email: '',
  password: '',
  confirmPassword: '',
  phone: '',
  street: '',
  suburb: '',
  state: '',
  postcode: '',
};

// Form validation logic, returns object with error messages for each field that fails
function validate(form) {
  // Address rules are shared with the account and checkout pages
  const errors = validateAddress(form);

  if (form.name.trim() === '') {
    errors.name = 'Enter your name.';
  }
  // Something@something.something
  if (!/^\S+@\S+\.\S+$/.test(form.email.trim())) {
    errors.email = 'Enter a valid email address.';
  }
  if (form.password.length < 8) {
    errors.password = 'Password must be at least 8 characters.';
  }
  if (form.confirmPassword !== form.password) {
    errors.confirmPassword = 'Passwords do not match.';
  }

  return errors;
}

function RegisterPage() {
  const navigate = useNavigate();
  const [form, setForm] = useState(EMPTY_FORM);
  const [errors, setErrors] = useState({});
  const [serverError, setServerError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Uses the input's id to know which field to update
  function handleChange(event) {
    setForm({ ...form, [event.target.id]: event.target.value });
  }

  async function handleSubmit(event) {
    event.preventDefault(); // stop the browser reloading the page!
    const newErrors = validate(form);
    setErrors(newErrors);
    setServerError('');

    // Business Scenario 3: ask the user to correct errors before anything is saved
    if (Object.keys(newErrors).length > 0) {
      return;
    }

    setIsSubmitting(true);
    try {
      const user = await registerCustomer(form);
      setForm(EMPTY_FORM);
      // Account created and logged in, so go straight to the account page
      navigate('/account', {
        state: { message: 'Your account has been created successfully. Welcome to the Guild, ' + user.name + '!' },
      });
    } catch (error) {
      if (error.isDuplicate) {
        setServerError(error.message);
      } else {
        setServerError('We could not create your account. Check that the API is running and try again.');
      }
      setIsSubmitting(false);
    }
  }

  // Returns label + input + error message for a field. Uses input's id to know which field to update/error message to show
  function field(id, label, type = 'text', extra = {}) {
    return (
      <>
        <label className="form-label fw-semibold" htmlFor={id}>{label}</label>
        <input
          aria-describedby={errors[id] ? id + '-error' : undefined}
          className={errors[id] ? 'form-control is-invalid' : 'form-control'}
          id={id}
          onChange={handleChange}
          type={type}
          value={form[id]}
          {...extra}
        />
        {errors[id] && <div className="invalid-feedback" id={id + '-error'}>{errors[id]}</div>}
      </>
    );
  }

  const errorCount = Object.keys(errors).length;

  return (
    <div className="app">
      <Navbar />
      <main className="container py-5" aria-labelledby="register-heading">
        <div className="row justify-content-center">
          <div className="col-lg-8">
            <div className="panel p-4 p-lg-5">
              <p className="eyebrow text-uppercase small fw-semibold mb-2">Join the Guild</p>
              <h1 className="h2 fw-bold mb-2" id="register-heading">Create an account</h1>
              <p className="text-muted mb-4">
                Already have one? <Link to="/login">Log in</Link>
              </p>

              {errorCount > 0 && (
                <div className="alert alert-danger" role="alert">
                  <i className="bi bi-exclamation-triangle me-1" aria-hidden="true" />
                  Please correct the {errorCount === 1 ? 'field' : errorCount + ' fields'} marked below.
                </div>
              )}
              {serverError && (
                <div className="alert alert-danger" role="alert">
                  <i className="bi bi-exclamation-triangle me-1" aria-hidden="true" />
                  {serverError}
                </div>
              )}

              <form noValidate onSubmit={handleSubmit}>
                <h2 className="h5 mb-3">Your details</h2>
                <div className="row g-3 mb-4">
                  <div className="col-md-6">{field('name', 'Full name', 'text', { autoComplete: 'name' })}</div>
                  <div className="col-md-6">{field('email', 'Email', 'email', { autoComplete: 'email' })}</div>
                  <div className="col-md-6">{field('password', 'Password', 'password', { autoComplete: 'new-password', title: 'At least 8 characters' })}</div>
                  <div className="col-md-6">
                    {field('confirmPassword', 'Confirm password', 'password', { autoComplete: 'new-password' })}
                  </div>
                </div>

                <h2 className="h5 mb-3">Contact and delivery address</h2>
                <div className="mb-4">
                  <AddressFields errors={errors} form={form} onChange={handleChange} />
                </div>

                <button className="btn btn-guild" disabled={isSubmitting} type="submit">
                  {isSubmitting ? 'Creating account…' : 'Create account'}
                </button>
              </form>
            </div>
          </div>
        </div>
      </main>
      <Footer />
    </div>
  );
}

export default RegisterPage;
